class HashingTest(unittest.TestCase):
    def test_roundtrip(self):
        for pw in ["", "a", "correct horse battery staple", "pässö中" * 100, "x" * 5000]:
            stored = m.hash_password(pw)
            self.assertTrue(stored.startswith("pbkdf2_sha256$"))
